import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/* ─── Resizable Group ───────────────────────────────────────── */

export interface ResizableGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  direction?: "horizontal" | "vertical";
  storageKey?: string;
}

type ResizablePanelConfig = {
  minSize: number;
  maxSize: number;
  collapsible: boolean;
};

export const ResizableGroup = React.forwardRef<HTMLDivElement, ResizableGroupProps>(
  ({ className, direction = "horizontal", storageKey, children, ...props }, ref) => {
    const containerRef = React.useRef<HTMLDivElement | null>(null);
    const combinedRef = useForkRef(ref, containerRef);

    const [sizes, setSizes] = React.useState<number[]>([]);

    // Retrieve list of resizable panels inside group
    const getPanels = React.useCallback(() => {
      const arr: React.ReactElement<any>[] = [];
      React.Children.forEach(children, (child) => {
        if (
          React.isValidElement(child) &&
          (child.type === ResizablePanel || (child.type as any).displayName === "ResizablePanel")
        ) {
          arr.push(child as React.ReactElement<any>);
        }
      });
      return arr;
    }, [children]);

    const persistSizes = React.useCallback(
      (nextSizes: number[]) => {
        if (!storageKey) return;

        try {
          localStorage.setItem(storageKey, JSON.stringify(nextSizes));
        } catch (err) {
          console.warn("Resizable: Failed saving state to storage", err);
        }
      },
      [storageKey]
    );

    const getPanelConfig = React.useCallback(
      (index: number): ResizablePanelConfig => {
        const panel = getPanels()[index]?.props ?? {};

        return {
          minSize: panel.minSize ?? 10,
          maxSize: panel.maxSize ?? 100,
          collapsible: panel.collapsible ?? false,
        };
      },
      [getPanels]
    );

    const resizePanelPair = React.useCallback(
      (baseSizes: number[], handleIndex: number, targetLeftSize: number) => {
        if (
          baseSizes.length === 0 ||
          handleIndex < 0 ||
          handleIndex + 1 >= baseSizes.length
        ) {
          return baseSizes;
        }

        const nextSizes = [...baseSizes];
        const sizeLeft = baseSizes[handleIndex];
        const sizeRight = baseSizes[handleIndex + 1];
        const totalCombined = sizeLeft + sizeRight;

        if (!Number.isFinite(totalCombined) || totalCombined <= 0) {
          return baseSizes;
        }

        const leftPanel = getPanelConfig(handleIndex);
        const rightPanel = getPanelConfig(handleIndex + 1);

        let newSizeLeft = targetLeftSize;
        let newSizeRight = totalCombined - targetLeftSize;

        // Left panel sizing constraints
        if (
          leftPanel.collapsible &&
          newSizeLeft < leftPanel.minSize / 2
        ) {
          newSizeRight += newSizeLeft;
          newSizeLeft = 0;
        } else {
          newSizeLeft = Math.max(
            leftPanel.minSize,
            Math.min(leftPanel.maxSize, newSizeLeft)
          );
          newSizeRight = totalCombined - newSizeLeft;
        }

        // Right panel sizing constraints, if left did not collapse
        if (newSizeLeft > 0) {
          if (
            rightPanel.collapsible &&
            newSizeRight < rightPanel.minSize / 2
          ) {
            newSizeLeft += newSizeRight;
            newSizeRight = 0;
          } else {
            newSizeRight = Math.max(
              rightPanel.minSize,
              Math.min(rightPanel.maxSize, newSizeRight)
            );
            newSizeLeft = totalCombined - newSizeRight;
          }
        }

        nextSizes[handleIndex] = newSizeLeft;
        nextSizes[handleIndex + 1] = newSizeRight;

        return nextSizes;
      },
      [getPanelConfig]
    );

    const getHandleValue = React.useCallback(
      (baseSizes: number[], handleIndex: number) => {
        const sizeLeft = baseSizes[handleIndex] ?? 0;
        const sizeRight = baseSizes[handleIndex + 1] ?? 0;
        const totalCombined = sizeLeft + sizeRight;
        const leftPanel = getPanelConfig(handleIndex);
        const rightPanel = getPanelConfig(handleIndex + 1);
        const min = leftPanel.collapsible ? 0 : leftPanel.minSize;
        const maxByRight = totalCombined - (rightPanel.collapsible ? 0 : rightPanel.minSize);
        const max = Math.max(min, Math.min(leftPanel.maxSize, maxByRight));
        const now = Math.max(min, Math.min(max, sizeLeft));

        return {
          min: roundSize(min),
          max: roundSize(max),
          now: roundSize(now),
        };
      },
      [getPanelConfig]
    );

    // Initial sizes calculations & load from storage
    React.useEffect(() => {
      const panels = getPanels();
      const count = panels.length;
      if (count === 0) return;

      if (storageKey) {
        try {
          const saved = localStorage.getItem(storageKey);
          if (saved) {
            const parsed = JSON.parse(saved);
            if (Array.isArray(parsed) && parsed.length === count) {
              setSizes(parsed);
              return;
            }
          }
        } catch (e) {
          console.warn("Resizable: Failed loading stored state", e);
        }
      }

      // Fallback: calculate sizes using defaultSize or split equally
      let remaining = 100;
      let undefCount = 0;
      const initial = panels.map((p) => {
        if (p.props.defaultSize !== undefined) {
          remaining -= p.props.defaultSize;
          return p.props.defaultSize;
        }
        undefCount++;
        return -1;
      });

      const fallback = undefCount > 0 ? Math.max(0, remaining / undefCount) : 0;
      const finalSizes = initial.map((s) => (s === -1 ? fallback : s));
      setSizes(finalSizes);
    }, [storageKey, getPanels]);

    const activeResizeRef = React.useRef<{
      handleIndex: number;
      initialPointer: number;
      initialSizes: number[];
      totalSize: number;
      lastSizes: number[];
    } | null>(null);

    const startResize = (handleIndex: number, e: React.PointerEvent) => {
      e.preventDefault();
      const container = containerRef.current;
      if (!container || handleIndex < 0 || handleIndex + 1 >= sizes.length) return;

      const rect = container.getBoundingClientRect();
      const totalSize = direction === "horizontal" ? rect.width : rect.height;
      if (totalSize <= 0) return;

      const initialPointer = direction === "horizontal" ? e.clientX : e.clientY;

      activeResizeRef.current = {
        handleIndex,
        initialPointer,
        initialSizes: [...sizes],
        totalSize,
        lastSizes: [...sizes],
      };

      // Drag capture starts
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      container.classList.add("select-none");
    };

    const handlePointerMove = (e: React.PointerEvent) => {
      const active = activeResizeRef.current;
      if (!active) return;

      const currentPointer = direction === "horizontal" ? e.clientX : e.clientY;
      const deltaPx = currentPointer - active.initialPointer;
      const deltaPct = (deltaPx / active.totalSize) * 100;

      const nextSizes = resizePanelPair(
        active.initialSizes,
        active.handleIndex,
        active.initialSizes[active.handleIndex] + deltaPct
      );

      active.lastSizes = nextSizes;
      setSizes(nextSizes);
    };

    const handlePointerUp = (e: React.PointerEvent) => {
      const active = activeResizeRef.current;
      if (!active) return;

      (e.target as HTMLElement).releasePointerCapture(e.pointerId);
      containerRef.current?.classList.remove("select-none");
      persistSizes(active.lastSizes);
      activeResizeRef.current = null;
    };

    const handleKeyDown = (handleIndex: number, e: React.KeyboardEvent) => {
      const step = e.shiftKey ? 10 : 2;
      let delta: number | null = null;
      let boundary: "min" | "max" | null = null;

      if (direction === "horizontal") {
        if (e.key === "ArrowLeft") {
          delta = -step;
        } else if (e.key === "ArrowRight") {
          delta = step;
        }
      } else if (e.key === "ArrowUp") {
        delta = -step;
      } else if (e.key === "ArrowDown") {
        delta = step;
      }

      if (e.key === "Home") {
        boundary = "min";
      } else if (e.key === "End") {
        boundary = "max";
      }

      if (delta === null && boundary === null) return;

      e.preventDefault();

      setSizes((currentSizes) => {
        const targetLeftSize =
          boundary === "min"
            ? getHandleValue(currentSizes, handleIndex).min
            : boundary === "max"
              ? getHandleValue(currentSizes, handleIndex).max
              : (currentSizes[handleIndex] ?? 0) + delta!;

        const nextSizes = resizePanelPair(
          currentSizes,
          handleIndex,
          targetLeftSize
        );
        persistSizes(nextSizes);
        return nextSizes;
      });
    };

    const toggleCollapse = (idx: number) => {
      if (sizes.length === 0) return;

      const panels = getPanels();
      const pLeft = panels[idx]?.props ?? {};
      const pRight = panels[idx + 1]?.props ?? {};

      const minLeft = pLeft.minSize ?? 10;
      const minRight = pRight.minSize ?? 10;

      const totalCombined = sizes[idx] + sizes[idx + 1];
      const nextSizes = [...sizes];

      // Double-click toggle collapsible panel logic
      if (sizes[idx] === 0 && pLeft.collapsible) {
        nextSizes[idx] = minLeft;
        nextSizes[idx + 1] = totalCombined - minLeft;
      } else if (sizes[idx + 1] === 0 && pRight.collapsible) {
        nextSizes[idx + 1] = minRight;
        nextSizes[idx] = totalCombined - minRight;
      } else {
        if (pLeft.collapsible) {
          nextSizes[idx] = 0;
          nextSizes[idx + 1] = totalCombined;
        } else if (pRight.collapsible) {
          nextSizes[idx + 1] = 0;
          nextSizes[idx] = totalCombined;
        }
      }

      setSizes(nextSizes);
      persistSizes(nextSizes);
    };

    let panelCounter = 0;

    return (
      <div
        ref={combinedRef}
        className={cn(
          "flex w-full h-full overflow-hidden",
          direction === "horizontal" ? "flex-row" : "flex-col",
          className
        )}
        {...props}
      >
        {React.Children.map(children, (child) => {
          if (!React.isValidElement(child)) return child;

          if (
            child.type === ResizablePanel ||
            (child.type as any).displayName === "ResizablePanel"
          ) {
            const currentIdx = panelCounter++;
            const currentSize = sizes[currentIdx];
            return React.cloneElement(child as React.ReactElement<any>, {
              size: currentSize,
              direction,
            });
          }

          if (
            child.type === ResizableHandle ||
            (child.type as any).displayName === "ResizableHandle"
          ) {
            const currentIdx = panelCounter - 1;
            const handleValue = getHandleValue(sizes, currentIdx);
            return React.cloneElement(child as React.ReactElement<any>, {
              direction,
              "aria-valuemin": handleValue.min,
              "aria-valuemax": handleValue.max,
              "aria-valuenow": handleValue.now,
              "aria-valuetext": `${handleValue.now}%`,
              onPointerDown: (e: React.PointerEvent) => startResize(currentIdx, e),
              onPointerMove: handlePointerMove,
              onPointerUp: handlePointerUp,
              onKeyDown: (e: React.KeyboardEvent) => handleKeyDown(currentIdx, e),
              onDoubleClick: () => toggleCollapse(currentIdx),
            });
          }

          return child;
        })}
      </div>
    );
  }
);
ResizableGroup.displayName = "ResizableGroup";

/* ─── Resizable Panel ───────────────────────────────────────── */

export interface ResizablePanelProps extends React.HTMLAttributes<HTMLDivElement> {
  defaultSize?: number;
  minSize?: number;
  maxSize?: number;
  collapsible?: boolean;
  size?: number; // Injected by Group
  direction?: "horizontal" | "vertical"; // Injected by Group
}

export const ResizablePanel = React.forwardRef<HTMLDivElement, ResizablePanelProps>(
  ({ className, defaultSize, minSize, maxSize, collapsible, size, direction, style, ...props }, ref) => {
    const currentSize = size !== undefined ? size : defaultSize;

    const panelStyle: React.CSSProperties = {
      ...style,
      flexGrow: currentSize !== undefined ? currentSize : 1,
      flexShrink: currentSize !== undefined ? 0 : 1,
      flexBasis: currentSize !== undefined ? `${currentSize}%` : "0px",
    };

    if (currentSize === 0) {
      panelStyle.display = "none";
    }

    return (
      <div
        ref={ref}
        style={panelStyle}
        className={cn(
          "transition-[flex-grow,flex-basis,display] duration-200 ease-out overflow-hidden",
          className
        )}
        {...props}
      />
    );
  }
);
ResizablePanel.displayName = "ResizablePanel";

/* ─── Resizable Handle ──────────────────────────────────────── */

export interface ResizableHandleProps extends React.HTMLAttributes<HTMLDivElement> {
  direction?: "horizontal" | "vertical"; // Injected by Group
}

export const ResizableHandle = React.forwardRef<HTMLDivElement, ResizableHandleProps>(
  ({ className, direction = "horizontal", ...props }, ref) => {
    const isHorizontal = direction === "horizontal";

    return (
      <div
        ref={ref}
        role="separator"
        aria-orientation={isHorizontal ? "vertical" : "horizontal"}
        tabIndex={0}
        className={cn(
          "group relative flex items-center justify-center select-none touch-none z-10 transition-colors duration-150 outline-none",
          "focus-visible:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-[#cd1c18]/40 dark:focus-visible:bg-white/[0.03] dark:focus-visible:ring-red-400/40",
          isHorizontal
            ? "w-2 h-full cursor-col-resize hover:bg-zinc-100 dark:hover:bg-white/[0.02]"
            : "h-2 w-full cursor-row-resize hover:bg-zinc-100 dark:hover:bg-white/[0.02]",
          className
        )}
        {...props}
      >
        {/* Visual Line inside Handle */}
        <div
          className={cn(
            "rounded-full bg-zinc-200 dark:bg-white/[0.08] transition-colors duration-150",
            "group-hover:bg-[#cd1c18] dark:group-hover:bg-red-400",
            "hover:bg-[#cd1c18] dark:hover:bg-red-400",
            isHorizontal ? "w-[2px] h-8" : "h-[2px] w-8"
          )}
        />
      </div>
    );
  }
);
ResizableHandle.displayName = "ResizableHandle";

/* ─── Ref Forker Helper ─────────────────────────────────────── */

function useForkRef<T>(
  refA: React.Ref<T> | undefined,
  refB: React.Ref<T> | undefined
): React.RefCallback<T> | null {
  return React.useMemo(() => {
    if (refA == null && refB == null) return null;
    return (value) => {
      setRef(refA, value);
      setRef(refB, value);
    };
  }, [refA, refB]);
}

function setRef<T>(ref: React.Ref<T> | undefined, value: T | null) {
  if (typeof ref === "function") {
    ref(value);
  } else if (ref && "current" in ref) {
    (ref as React.MutableRefObject<T | null>).current = value;
  }
}

function roundSize(value: number) {
  return Math.round(value * 100) / 100;
}
